package source

import (
	"fmt"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
)

// Every diagnostic here is about content that arrived intact and is not what the
// asset said it was, so none of them names a host, a commit or a credential.
// What each one names is the asset, because the edit that fixes it is in
// `harnaas.json` or in the source the entry points at, and a reader who has both
// open needs to know which entry to look at first.

// ShapeError reports content whose shape is not the one its asset type requires.
//
// The expected and the found shape are both carried as text rather than derived
// from the type at render time, because the two halves of the sentence come from
// two different places — the type's rule, and the directory somebody is looking
// at — and a message that restated the rule twice would leave the reader to work
// out which half was the observation.
type ShapeError struct {
	// AssetID is the asset whose source was verified.
	AssetID string

	// Type is the asset's type, which is where the requirement comes from.
	Type manifest.AssetType

	// Expected is the shape the type requires, in the words the message uses.
	Expected string

	// Found is what the source resolved to instead.
	Found string
}

// Error states the problem and then the fix, as every user-facing diagnostic
// does.
func (e *ShapeError) Error() string {
	return fmt.Sprintf(
		"the asset %q is a %s, which must be %s, and its source is %s\n\n"+
			"Point the entry at %s, or change the entry's %q in %s to match what the source is.",
		e.AssetID, e.Type, e.Expected, e.Found,
		e.Expected, "type", manifest.FileName,
	)
}

// MissingSkillFileError reports a skill directory with no SKILL.md in it.
//
// It is separate from [ShapeError] because the source is the right shape and the
// edit is in the content rather than in the manifest: adding a file, or pointing
// the entry one directory deeper. Reporting it as a shape mismatch would send an
// author to change a `type` that is correct.
type MissingSkillFileError struct {
	// AssetID is the asset whose source was verified.
	AssetID string

	// Source is the path the entry declared, as the manifest spells it.
	Source string
}

// Error states the problem and then the fix.
func (e *MissingSkillFileError) Error() string {
	return fmt.Sprintf(
		"the skill %q reads from %s, which holds no %s\n\n"+
			"Add %s to %s, or point the entry at the directory that has one.",
		e.AssetID, e.Source, SkillFileName,
		SkillFileName, e.Source,
	)
}

// SkillFrontmatterError reports a SKILL.md harnaas could not read a name out of.
//
// Absent, unparseable and present-without-a-name are one diagnostic with three
// reasons rather than three types, because the reader's next action is the same
// in all three — open the file and look at the top of it — and the reason is
// what tells them what they will find when they do.
type SkillFrontmatterError struct {
	// AssetID is the asset whose source was verified.
	AssetID string

	// Reason is what is wrong with the block, in the words the message uses.
	Reason string

	// Err is the parse failure where there was one, kept so the position the
	// YAML parser reported stays inspectable. It is nil for the two reasons that
	// are not parse failures.
	Err error
}

// Error states the problem and then the fix.
func (e *SkillFrontmatterError) Error() string {
	return fmt.Sprintf(
		"the skill %q has a %s harnaas cannot read a name from: %s\n\n"+
			"Give %s a frontmatter block whose %q is %q, between two %q lines at the top of the file.",
		e.AssetID, SkillFileName, e.Reason,
		SkillFileName, "name", e.AssetID, "---",
	)
}

// Unwrap keeps the parse failure inspectable where there was one.
func (e *SkillFrontmatterError) Unwrap() error { return e.Err }

// SkillNameMismatchError reports a skill whose frontmatter names something other
// than the asset it is installed as.
//
// This is the failure the whole check exists for. A harness that reads the
// `name` field uses it to decide the skill exists at all, so a mismatch installs
// cleanly, reports success and is never invoked — which is the one outcome a
// tool whose purpose is telling a team what is in effect must not produce.
// harnaas refuses rather than rewriting the field, because `SKILL.md` is the
// author's file and a frontmatter harnaas re-serialized is not the one they
// reviewed.
type SkillNameMismatchError struct {
	// AssetID is the id harnaas installs the skill as, declared by the entry or
	// inferred from its path.
	AssetID string

	// DeclaredName is the name the skill's own frontmatter gives.
	DeclaredName string
}

// Error states the problem and then the fix.
func (e *SkillNameMismatchError) Error() string {
	return fmt.Sprintf(
		"the skill installs as %q and its %s declares the name %q, and a harness reading that field would not find it\n\n"+
			"Set the frontmatter %q to %q, or give the entry an %q of %q in %s.",
		e.AssetID, SkillFileName, e.DeclaredName,
		"name", e.AssetID, "id", e.DeclaredName, manifest.FileName,
	)
}

package source_test

import (
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/source"
)

func TestFrontmatterIsSplitFromTheBodyItPrecedes(t *testing.T) {
	t.Parallel()

	block, present := source.SplitFrontmatter([]byte("---\nname: review\n---\n# Review\n\nProse.\n"))

	require.True(t, present)
	assert.Equal(t, "name: review\n", string(block.Raw))
	assert.Equal(t, "# Review\n\nProse.\n", string(block.Body))
}

// TestFrontmatterWrittenWithCarriageReturnsIsRecognized keeps the check from
// depending on which machine committed the skill: a file checked out with CRLF
// endings opens with the same three characters and one more byte.
func TestFrontmatterWrittenWithCarriageReturnsIsRecognized(t *testing.T) {
	t.Parallel()

	block, present := source.SplitFrontmatter([]byte("---\r\nname: review\r\n---\r\nbody\r\n"))

	require.True(t, present)
	assert.Equal(t, "name: review\r\n", string(block.Raw))

	var declared struct {
		Name string `yaml:"name"`
	}
	require.NoError(t, block.Decode(&declared))
	assert.Equal(t, "review", declared.Name)
}

func TestADocumentWithNoFrontmatterReportsNoBlock(t *testing.T) {
	t.Parallel()

	for name, content := range map[string]string{
		"prose only":            "# Review\n",
		"delimiter below prose": "# Review\n---\nname: review\n---\n",
		"never closed":          "---\nname: review\n",
		"empty":                 "",
	} {
		t.Run(name, func(t *testing.T) {
			t.Parallel()

			_, present := source.SplitFrontmatter([]byte(content))
			assert.False(t, present)
		})
	}
}

// TestAHorizontalRuleInTheBodyDoesNotExtendTheBlock pins the closing delimiter
// to a whole line. A body beginning with a Markdown rule is common, and a match
// on the prefix would swallow the prose above it into the frontmatter.
func TestAHorizontalRuleInTheBodyDoesNotExtendTheBlock(t *testing.T) {
	t.Parallel()

	block, present := source.SplitFrontmatter([]byte("---\nname: review\n---\nintro\n\n----\n\nmore\n"))

	require.True(t, present)
	assert.Equal(t, "name: review\n", string(block.Raw))
	assert.Equal(t, "intro\n\n----\n\nmore\n", string(block.Body))
}

// TestAnEmptyBlockSplitsAndDecodesToNothing covers the document that declares a
// block and puts nothing in it, which is a skill with no name rather than a
// skill with no frontmatter — two reasons the caller reports separately.
func TestAnEmptyBlockSplitsAndDecodesToNothing(t *testing.T) {
	t.Parallel()

	block, present := source.SplitFrontmatter([]byte("---\n---\nbody\n"))

	require.True(t, present)
	assert.Empty(t, block.Raw)

	var declared struct {
		Name string `yaml:"name"`
	}
	require.NoError(t, block.Decode(&declared))
	assert.Empty(t, declared.Name)
}

// TestUnknownFieldsAreIgnored records that harnaas is one reader of a block that
// belongs to its author: a skill carrying fields for other harnesses decodes.
func TestUnknownFieldsAreIgnored(t *testing.T) {
	t.Parallel()

	block, present := source.SplitFrontmatter([]byte("---\nname: review\nallowed-tools: [Read]\nlicense: MIT\n---\n"))
	require.True(t, present)

	var declared struct {
		Name string `yaml:"name"`
	}
	require.NoError(t, block.Decode(&declared))
	assert.Equal(t, "review", declared.Name)
}

func TestABlockThatIsNotYAMLFailsToDecode(t *testing.T) {
	t.Parallel()

	block, present := source.SplitFrontmatter([]byte("---\nname: [review\n---\nbody\n"))
	require.True(t, present)

	var declared struct {
		Name string `yaml:"name"`
	}
	require.Error(t, block.Decode(&declared))
}

// TestTheBlockIsKeptExactlyAsItArrived is the pass-through guarantee stated as a
// test: the bytes a caller can reach are the bytes that were in the file, so
// nothing downstream can install a re-serialized frontmatter even by accident.
func TestTheBlockIsKeptExactlyAsItArrived(t *testing.T) {
	t.Parallel()

	const raw = "name:   review\n# a comment nobody should lose\ndescription: >-\n  folded\n  text\n"

	block, present := source.SplitFrontmatter([]byte("---\n" + raw + "---\nbody\n"))

	require.True(t, present)
	assert.Equal(t, raw, string(block.Raw))
}

package source_test

import (
	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/source"
)

// verifiable builds the request and the resolved source verification is handed,
// exactly as the registry would: the asset carries the type and the id, and the
// files carry the paths the kind produced relative to what the entry named.
func verifiable(
	tb testing.TB,
	assetType manifest.AssetType,
	id, subtree string,
	content map[string][]byte,
) (source.Request, *source.Resolved) {
	tb.Helper()

	resolved, err := source.NewResolved(
		source.Provenance{Kind: manifest.SourceKindLocal, Source: subtree},
		content,
	)
	require.NoError(tb, err)

	req := source.Request{
		Asset: manifest.Asset{Type: assetType, ID: id, Ref: manifest.AssetRef{Path: subtree}},
	}
	return req, resolved
}

// skillDocument is a SKILL.md declaring the given name.
func skillDocument(name string) []byte {
	return []byte("---\nname: " + name + "\ndescription: Reviews code.\n---\n\n# Review\n")
}

func TestASkillDirectoryNamingItselfCorrectlyVerifies(t *testing.T) {
	t.Parallel()

	req, resolved := verifiable(t, manifest.AssetTypeSkill, "review", "skills/review", map[string][]byte{
		"SKILL.md":              skillDocument("review"),
		"references/checks.md":  []byte("checks\n"),
		"references/rubric.md":  []byte("rubric\n"),
		"scripts/collect.sh":    []byte("#!/bin/sh\n"),
		"references/README.txt": []byte("read me\n"),
	})

	require.NoError(t, source.Verify(req, resolved))
}

// TestVerificationRewritesNothing is the read-only half of the name check. The
// bytes are compared after a run that had every reason to touch them.
func TestVerificationRewritesNothing(t *testing.T) {
	t.Parallel()

	document := skillDocument("review")
	original := string(document)

	req, resolved := verifiable(t, manifest.AssetTypeSkill, "review", "skills/review", map[string][]byte{
		"SKILL.md": document,
	})
	require.NoError(t, source.Verify(req, resolved))

	assert.Equal(t, original, string(resolved.Files[0].Content))
}

func TestASkillResolvingToASingleFileIsRefusedAsTheWrongShape(t *testing.T) {
	t.Parallel()

	req, resolved := verifiable(t, manifest.AssetTypeSkill, "review", "skills/review.md", map[string][]byte{
		"review.md": skillDocument("review"),
	})

	err := source.Verify(req, resolved)

	var shape *source.ShapeError
	require.ErrorAs(t, err, &shape)
	assert.Equal(t, "review", shape.AssetID)
	assert.Equal(t, manifest.AssetTypeSkill, shape.Type)
	assert.Contains(t, shape.Expected, "directory")
	assert.Equal(t, "a single file", shape.Found)
}

func TestASkillDirectoryWithNoSkillFileNamesTheMissingFile(t *testing.T) {
	t.Parallel()

	req, resolved := verifiable(t, manifest.AssetTypeSkill, "review", "skills/review", map[string][]byte{
		"readme.md":            []byte("# Review\n"),
		"references/checks.md": []byte("checks\n"),
	})

	err := source.Verify(req, resolved)

	var missing *source.MissingSkillFileError
	require.ErrorAs(t, err, &missing)
	assert.Equal(t, "review", missing.AssetID)
	assert.Equal(t, "skills/review", missing.Source)
	assert.Contains(t, err.Error(), source.SkillFileName)
}

func TestAPersonaResolvingToADirectoryIsRefused(t *testing.T) {
	t.Parallel()

	req, resolved := verifiable(t, manifest.AssetTypePersona, "reviewer", "agents/reviewer", map[string][]byte{
		"reviewer.md": []byte("# Reviewer\n"),
		"notes.md":    []byte("notes\n"),
	})

	err := source.Verify(req, resolved)

	var shape *source.ShapeError
	require.ErrorAs(t, err, &shape)
	assert.Equal(t, "a single file", shape.Expected)
	assert.Equal(t, "a directory holding 2 files", shape.Found)
}

// TestEveryNonSkillTypeIsHeldToTheSingleFileShape runs the rule over all four
// types, because the shape requirement belongs to "not a skill" rather than to
// any one of them, and a switch that grew a case would otherwise be silent.
func TestEveryNonSkillTypeIsHeldToTheSingleFileShape(t *testing.T) {
	t.Parallel()

	subtrees := map[manifest.AssetType]string{
		manifest.AssetTypeRule:        "rules/house-style",
		manifest.AssetTypeInstruction: "instructions/context",
		manifest.AssetTypeCommand:     "commands/ship",
		manifest.AssetTypePersona:     "agents/reviewer",
	}

	for assetType, subtree := range subtrees {
		t.Run(string(assetType), func(t *testing.T) {
			t.Parallel()

			id := path(subtree)

			single, resolvedSingle := verifiable(t, assetType, id, subtree+".md", map[string][]byte{
				id + ".md": []byte("content\n"),
			})
			require.NoError(t, source.Verify(single, resolvedSingle))

			many, resolvedMany := verifiable(t, assetType, id, subtree, map[string][]byte{
				"one.md": []byte("one\n"),
				"two.md": []byte("two\n"),
			})
			err := source.Verify(many, resolvedMany)

			var shape *source.ShapeError
			require.ErrorAs(t, err, &shape)
			assert.Contains(t, err.Error(), id, "the diagnostic names the asset")
			assert.Contains(t, err.Error(), string(assetType), "the diagnostic names the type")
		})
	}
}

// TestADirectoryHoldingOneFileIsStillADirectory keeps the count in the message
// honest for the case that reads most like a single file.
func TestADirectoryHoldingOneFileIsStillADirectory(t *testing.T) {
	t.Parallel()

	req, resolved := verifiable(t, manifest.AssetTypeRule, "house-style", "rules/house-style", map[string][]byte{
		"house-style.md.txt": []byte("content\n"),
	})

	err := source.Verify(req, resolved)

	var shape *source.ShapeError
	require.ErrorAs(t, err, &shape)
	assert.Equal(t, "a directory holding 1 file", shape.Found)
}

func TestASkillNameThatDisagreesWithTheIDReportsBothNames(t *testing.T) {
	t.Parallel()

	req, resolved := verifiable(t, manifest.AssetTypeSkill, "review", "skills/review", map[string][]byte{
		"SKILL.md": skillDocument("code-review"),
	})

	err := source.Verify(req, resolved)

	var mismatch *source.SkillNameMismatchError
	require.ErrorAs(t, err, &mismatch)
	assert.Equal(t, "review", mismatch.AssetID)
	assert.Equal(t, "code-review", mismatch.DeclaredName)
	assert.Contains(t, err.Error(), `"review"`)
	assert.Contains(t, err.Error(), `"code-review"`)
}

// TestASkillFileHarnaasCannotReadANameFromIsReported covers the three ways the
// name is unavailable, which are one diagnostic with three reasons because the
// reader's next action is the same in all of them.
func TestASkillFileHarnaasCannotReadANameFromIsReported(t *testing.T) {
	t.Parallel()

	documents := map[string]struct {
		content []byte
		reason  string
		wrapped bool
	}{
		"absent":      {content: []byte("# Review\n\nProse.\n"), reason: "no frontmatter"},
		"unterminated": {
			content: []byte("---\nname: review\n"),
			reason:  "no frontmatter",
		},
		"unparseable": {
			content: []byte("---\nname: [review\ndescription: x\n---\n"),
			reason:  "not valid YAML",
			wrapped: true,
		},
		"nameless": {content: []byte("---\ndescription: Reviews code.\n---\n"), reason: "no name"},
	}

	for name, document := range documents {
		t.Run(name, func(t *testing.T) {
			t.Parallel()

			req, resolved := verifiable(t, manifest.AssetTypeSkill, "review", "skills/review", map[string][]byte{
				"SKILL.md": document.content,
			})

			err := source.Verify(req, resolved)

			var frontmatter *source.SkillFrontmatterError
			require.ErrorAs(t, err, &frontmatter)
			assert.Equal(t, "review", frontmatter.AssetID)
			assert.Contains(t, frontmatter.Reason, document.reason)
			assert.Contains(t, err.Error(), source.SkillFileName, "the diagnostic names the file")

			if document.wrapped {
				assert.Error(t, frontmatter.Err, "a parse failure stays inspectable")
			}
		})
	}
}

// TestEveryVerificationFailureIsShapedProblemThenFix holds the new diagnostics
// to the shape every user-facing message in harnaas has.
func TestEveryVerificationFailureIsShapedProblemThenFix(t *testing.T) {
	t.Parallel()

	failures := map[string]error{
		"shape": &source.ShapeError{
			AssetID:  "review",
			Type:     manifest.AssetTypeSkill,
			Expected: "a directory containing " + source.SkillFileName,
			Found:    "a single file",
		},
		"missing skill file": &source.MissingSkillFileError{AssetID: "review", Source: "skills/review"},
		"frontmatter":        &source.SkillFrontmatterError{AssetID: "review", Reason: "it has no frontmatter block"},
		"name mismatch":      &source.SkillNameMismatchError{AssetID: "review", DeclaredName: "code-review"},
	}

	for name, err := range failures {
		t.Run(name, func(t *testing.T) {
